'use strict';
const FOOD_TRADE_UI9={bakeryView,logisticsView,bind};
function foodFleetPanel9(){const root=state.foodTrade9,last=root.history.at(-1);return `<section class="card" style="margin-top:24px"><div class="card-head"><h2>Ranní rozvozová flotila</h2><button class="primary" id="foodVehicleBuy9">Pořídit dodávku</button></div><p class="sub">Vlastní vůz potřebuje skutečného placeného řidiče a městskou trasu. Kapacita se sdílí mezi kavárnami a odběrateli. Chladicí vůz zvládne studené sendviče; outsourcing zůstává placenou alternativou.</p>${rows([['Fixní provoz vozů a smluvní mzdy / týden',money(foodFleetFixed9())],['Minulý skutečný vlastní rozvoz',last?last.routes.reduce((n,r)=>n+r.units,0)+' ks · palivo '+money(last.routes.reduce((n,r)=>n+r.fuel,0)):'Ještě neproběhl']])}<div class="cards">${root.vehicles.map(v=>`<article class="food-plan-card5"><h3>${esc(v.name)}</h3><p class="sub">${FOOD_VEHICLES9[v.type].name} · ${esc(v.city)} · ${FOOD_VEHICLES9[v.type].capacity} ks/den · stav ${number(v.condition,1)} %</p><p>${esc(v.driver?.name||'Bez řidiče')} ${v.driver?'· '+money(v.driver.salary*cityWageFactor6(v.city))+'/týden':''}</p><div class="actions"><button class="soft" data-food-route9="${v.id}">Trasa a odjezd</button><button class="soft" data-food-driver9="${v.id}">${v.driver?'Odvolat řidiče':'Najmout řidiče'}</button><button class="soft" data-food-vehicle-service9="${v.id}">Servis · ${money(v.cost*.04)}</button></div></article>`).join('')||'<p class="empty">Nemáš žádné vozy ani řidiče. Outsourcing kupuješ za každou skutečnou dodávku.</p>'}</div><p class="sub">Vlastní mzdy, odvody, údržba a odpisy běží i při malé vytíženosti. Porovnej skutečné objemy a palivo s externí cenou; úspora na kus nestačí, pokud vůz stojí. Městská trasa má 1–8 zastávek a nejvýše jednu denní kapacitu vozu.</p></section>`;}
function foodTradePanel9(){const root=state.foodTrade9,last=root.history.at(-1);return `<section class="card" style="margin-top:24px"><div class="card-head"><h2>Pekárenský velkoobchod</h2><button class="primary" id="foodContractNew9" ${!state.bakery5.bakeries.length?'disabled':''}>Nový ranní odběratel</button></div><p class="sub">Hotel, kanceláře nebo partnerská kavárna. Smlouva je 25–300 kusů každý z šesti provozních dnů. Přijaté kusy mají skutečnou výrobní kapacitu, suroviny a rozvoz. Cena je čisté obchodní inkaso bez DPH; odmítnutá dodávka nevytváří tržbu.</p>${last?rows([['Skutečné přijaté dodávky',last.deliveries.reduce((n,d)=>n+d.delivered,0)+' ks'],['Čisté obchodní tržby',money(last.revenue)],['Spotřebované zásoby a rozvoz',money(last.cost)],['Nepřijaté sjednané kusy',last.missing]]):''}<table class="data"><thead><tr><th>Odběratel / výroba</th><th>Ks / den</th><th>Čistá cena</th><th>Ranní požadavek</th><th>Stav</th></tr></thead><tbody>${root.contracts.map(c=>`<tr><td>${esc(c.name)}<small>${esc(bakeryById5(c.bakery)?.name||'Výroba')}</small></td><td>${c.qty}</td><td>${money(c.price)}</td><td>${number(c.deadline,1)} h · max. ${c.maxAge} h od výroby ${c.cold?'· chlad':''}</td><td>${c.status==='active'?`<button class="soft" data-food-contract-toggle9="${c.id}">${c.enabled?'Pozastavit':'Obnovit'}</button><button class="quiet" data-food-contract-cancel9="${c.id}">Ukončit</button>`:esc(c.status)}</td></tr>`).join('')}</tbody></table><h3>Otevřené reklamace</h3>${root.complaints.filter(c=>c.status==='open').slice(-20).map(c=>`<div class="report-row5"><p>T${c.week} · ${esc(root.contracts.find(r=>r.id===c.contract)?.name||'Odběratel')} · ${c.missing} ks nepřijato. ${esc(c.reason)}</p><button class="soft" data-food-claim9="${c.id}">Řešit reklamaci</button></div>`).join('')||'<p class="sub">Žádné otevřené reklamace.</p>'}${last?.deliveries.length?'<button class="soft" id="foodTradeReport9">Otevřít skutečné ranní dodávky</button>':''}</section>`;}
bakeryView=function(){return FOOD_TRADE_UI9.bakeryView()+foodTradePanel9()+foodFleetPanel9();};
logisticsView=function(){return foodFleetPanel9()+FOOD_TRADE_UI9.logisticsView();};
function foodVehicleDialog9(){show(`<h2>Pořídit rozvozový vůz</h2><div class="fields">${field('Název','<input id="foodVehicleName9" maxlength="40" value="Ranní rozvoz">')}${field('Typ',`<select id="foodVehicleType9">${Object.entries(FOOD_VEHICLES9).map(([id,v])=>option(id,v.name+' · '+money(v.cost))).join('')}</select>`)}${field('Město',`<select id="foodVehicleCity9">${CITIES.map(c=>option(c.name,c.name)).join('')}</select>`)}</div><p class="sub">Řidič není v kupní ceně. Nábor 8 000 Kč a smluvní mzda od 7 500 Kč/týden plus místní úprava a odvody. Po koupi nastav skutečnou trasu.</p><button class="primary" id="foodVehicleConfirm9">Prověřit investici</button>`);el('foodVehicleConfirm9').onclick=()=>{try{const q=foodVehicleQuote9(el('foodVehicleType9').value,el('foodVehicleCity9').value,el('foodVehicleName9').value);confirmAction('Koupit dodávku?',esc(q.name)+' · '+money(q.cost)+' bez řidiče. Týdenní údržba '+money(FOOD_VEHICLES9[q.type].upkeep)+' plus odpisy.',()=>buyFoodVehicle9(q.type,q.city,q.name,q),'Koupit vůz');}catch(e){toast(e.message);}};}
function foodRouteDialog9(id){const v=foodVehicle9(id),r=state.foodTrade9.routes.find(r=>r.vehicle===id)||{enabled:true,fallback:true,departure:6,stops:[]},stops=[...state.stores.filter(s=>!s.franchise&&loc(s.id).city===v.city).map(s=>({id:s.id,name:loc(s.id).name})),...FOOD_CLIENTS9.filter(c=>c.city===v.city)];show(`<h2>Trasa · ${esc(v.name)}</h2>${field('Odjezd / hodina',input('foodRouteDeparture9',r.departure,5.5,9,.25))}<label class="checkbox-line"><input id="foodRouteEnabled9" type="checkbox" ${r.enabled?'checked':''}> Aktivní městská trasa</label><label class="checkbox-line"><input id="foodRouteFallback9" type="checkbox" ${r.fallback?'checked':''}> Při nedostupném řidiči nebo chladu použít placený outsourcing</label><p class="sub">Pořadí určuje příjezd, každá další zastávka přidá čas. Všechny skutečné kusy se vejdou do jedné kapacity ${FOOD_VEHICLES9[v.type].capacity} ks/den. Bez placeného řidiče vůz nejede.</p>${stops.map(s=>field(s.name,`<select data-food-route-stop9="${s.id}">${option(0,'Mimo trasu',r.stops.includes(s.id)?r.stops.indexOf(s.id)+1:0)}${[1,2,3,4,5,6,7,8].map(n=>option(n,n+'. zastávka',r.stops.indexOf(s.id)+1)).join('')}</select>`)).join('')}<button class="primary" id="foodRouteSave9">Prověřit trasu</button>`);el('foodRouteSave9').onclick=()=>{try{const positions=[...document.querySelectorAll('[data-food-route-stop9]')].map(e=>({id:e.dataset.foodRouteStop9,rank:Number(e.value)})).filter(x=>x.rank);if(new Set(positions.map(x=>x.rank)).size!==positions.length)throw Error('Každá zastávka má jiné pořadí.');const data={enabled:el('foodRouteEnabled9').checked,fallback:el('foodRouteFallback9').checked,departure:Number(el('foodRouteDeparture9').value),stops:positions.sort((a,b)=>a.rank-b.rank).map(x=>x.id)},q=foodRouteQuote9(id,data);confirmAction('Uložit městskou trasu?',data.stops.length+' zastávek, odjezd '+data.departure+' h. Trasa nic nenaloží ani nezaplatí, dokud nevznikne skutečná dodávka.',()=>setFoodRoute9(id,data,q),'Uložit trasu');}catch(e){toast(e.message);}};}
function foodContractDialog9(){show(`<h2>Ranní pekárenský odběr</h2><div class="fields">${field('Pekárna',`<select id="foodContractBakery9">${state.bakery5.bakeries.map(b=>option(b.id,b.name)).join('')}</select>`)}${field('Odběratel',`<select id="foodContractClient9">${FOOD_CLIENTS9.filter(c=>state.bakery5.bakeries.some(b=>b.city===c.city)&&!state.foodTrade9.contracts.some(x=>x.client===c.id&&x.status==='active')).map(c=>option(c.id,c.name)).join('')}</select>`)}${field('Receptura',`<select id="foodContractRecipe9">${state.bakery5.recipes.map(r=>option(r.id,foodRecipe5(r.id).name)).join('')}</select>`)}${field('Ks každý provozní den',input('foodContractQty9',50,25,300))}${field('Délka / týdny',`<select id="foodContractWeeks9">${option(4,'4 týdny')}${option(13,'13 týdnů')}</select>`)}${field('Priorita výroby',`<select id="foodContractPriority9">${option('after','Po zásobování vlastní sítě')}${option('before','Před vlastní sítí')}</select>`)}</div><p class="sub">Sjednání 4 000 Kč. Skutečná cena, ranní deadline a čerstvost jsou v následné čisté nabídce. Smlouva vyžaduje výrobnu ve stejném městě.</p><button class="primary" id="foodContractPreview9">Otevřít nabídku</button>`);el('foodContractPreview9').onclick=()=>{try{const data={bakery:el('foodContractBakery9').value,client:el('foodContractClient9').value,recipe:el('foodContractRecipe9').value,qty:Number(el('foodContractQty9').value),weeks:Number(el('foodContractWeeks9').value),priority:el('foodContractPriority9').value,enabled:true},q=foodContractQuote9(data);confirmAction('Sjednat ranní odběr?',esc(q.clientName)+' · '+data.qty+' ks/den za '+money(q.price)+' čistého inkasa/kus. Příjezd do '+q.deadline+' h a max. '+q.maxAge+' h od výroby'+(q.cold?', chladicí přeprava':'')+'. Poplatek '+money(q.fee)+'. Nedodané kusy nemají tržbu a mohou vyvolat reklamaci.',()=>signFoodContract9(data,q),'Sjednat odběr');}catch(e){toast(e.message);}};}
bind=function(){FOOD_TRADE_UI9.bind();if(el('foodVehicleBuy9'))el('foodVehicleBuy9').onclick=foodVehicleDialog9;if(el('foodContractNew9'))el('foodContractNew9').onclick=foodContractDialog9;on('[data-food-route9]',b=>foodRouteDialog9(b.dataset.foodRoute9));on('[data-food-driver9]',b=>{const v=foodVehicle9(b.dataset.foodDriver9);if(v.driver)return confirmAction('Odvolat řidiče?',esc(v.driver.name)+' přestane mít smluvní mzdu; bez řidiče se vlastní trasa zastaví.',()=>releaseFoodDriver9(v.id));show(`<h2>Řidič · ${esc(v.name)}</h2>${DRIVER_POOL9.filter(p=>!state.foodTrade9.vehicles.some(v=>v.driver?.pid===p.pid)).map(p=>`<p>${esc(p.name)} · ${money(p.salary*cityWageFactor6(v.city))}/týden <button class="soft" data-food-driver-hire9="${p.pid}">Nábor 8 000 Kč</button></p>`).join('')}`);on('[data-food-driver-hire9]',b=>confirmAction('Přijmout řidiče?', '8 000 Kč nyní a smluvní mzda i během nevyužitého týdne. Odvody se přičtou ve výsledku firmy.',()=>hireFoodDriver9(v.id,b.dataset.foodDriverHire9)));});on('[data-food-vehicle-service9]',b=>confirmAction('Servis dodávky?',money(foodVehicle9(b.dataset.foodVehicleService9).cost*.04)+' za obnovení stavu na 100 %.',()=>serviceFoodVehicle9(b.dataset.foodVehicleService9)));on('[data-food-contract-toggle9]',b=>act(()=>{const c=state.foodTrade9.contracts.find(c=>c.id===b.dataset.foodContractToggle9);setFoodContractEnabled9(c.id,!c.enabled);},'Mandát změněn.'));on('[data-food-contract-cancel9]',b=>confirmAction('Ukončit ranní odběr?', 'Budoucí výroba a dodávky této smlouvy se zastaví. Staré skutečné dodávky a reklamace zůstanou v historii.',()=>cancelFoodContract9(b.dataset.foodContractCancel9)));on('[data-food-claim9]',b=>{try{const q=foodComplaintQuote9(b.dataset.foodClaim9,'credit');show(`<h2>Řešit reklamaci</h2><p>${q.missing} sjednaných kusů nebylo přijato. Kompenzace stojí ${money(q.cost)}; nejde o vrácení zaplaceného, nedodané kusy neměly tržbu.</p><div class="actions"><button class="primary" id="foodClaimCredit9">Zaplatit kompenzaci</button><button class="soft" id="foodClaimExplain9">Vysvětlit bez platby · důvěra −1</button></div>`);el('foodClaimCredit9').onclick=()=>act(()=>{resolveFoodComplaint9(q.id,'credit',q);el('modal').close();},'Kompenzace zaplacena.');el('foodClaimExplain9').onclick=()=>act(()=>{resolveFoodComplaint9(q.id,'explain');el('modal').close();},'Reklamace uzavřena.');}catch(e){toast(e.message);}});if(el('foodTradeReport9'))el('foodTradeReport9').onclick=()=>{const h=state.foodTrade9.history.at(-1);show(`<h2>Ranní dodávky · T${h.week}</h2><table class="data"><thead><tr><th>Den / odběratel</th><th>Sjednáno / přijato</th><th>Příjezd</th><th>Čisté tržby</th><th>Výsledek</th></tr></thead><tbody>${h.deliveries.map(d=>`<tr><td>${['Po','Út','St','Čt','Pá','So'][d.day]} · ${esc(FOOD_CLIENTS9.find(c=>c.id===d.client).name)}</td><td>${d.ordered} / ${d.delivered}</td><td>${number(d.clock,2)} h · ${d.cold?'chlad':'běžný vůz'}</td><td>${money(d.revenue)}</td><td>${esc(d.reason)}</td></tr>`).join('')}</tbody></table>`);};};render();
